insert into public.reviews
  (id, consultancy_id, branch_id, user_id, status, country, study_level, intake_year, outcome, service_charge_npr, extra_costs_npr, extra_costs_note, rating_honesty, rating_communication, rating_documents, rating_speed, rating_after_visa, went_well, went_badly, would_recommend, is_verified, invited_by_consultancy, display_name_choice, rejection_reason, created_at, approved_at)
values
  ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', null, 'd0000000-0000-4000-8000-000000000001', 'approved', 'AU', 'language', 2026, 'in_process', 65000, 22000, 'Courier and document translation.', 3, 3, 4, 4, 3, 'मेरो अभिभावकलाई सबै कुरा नेपालीमा राम्ररी बुझाइदिनुभयो। भिसा पक्का हुन्छ भनेर कहिल्यै भन्नुभएन।', 'They pushed one college strongly. I felt they did not want to show me other options.', false, false, true, 'anonymous', null, '2026-09-04T06:00:00.000Z', '2026-09-06T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000001', null, 'd0000000-0000-4000-8000-000000000002', 'approved', 'GB', 'master', 2026, 'in_process', 90000, null, null, 5, 4, 4, 4, 4, 'They gave me a checklist on the first day. It made the bank and police documents easy.', 'Nothing serious. The waiting room is small and gets very crowded in the afternoon.', true, true, false, 'name', null, '2026-07-13T06:00:00.000Z', '2026-07-15T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000001', null, 'd0000000-0000-4000-8000-000000000003', 'approved', 'GB', 'diploma', 2024, 'visa_granted', 90000, null, null, 3, 3, 3, 4, null, 'Replies came the same day, even on Saturdays. I always knew what the next step was.', 'They pushed one college strongly. I felt they did not want to show me other options.', true, false, false, 'name', null, '2026-02-25T06:00:00.000Z', '2026-02-27T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000004', 'pending', 'AU', 'bachelor', 2026, 'visa_refused', 50000, null, null, 4, 3, 4, 3, 3, 'They checked my statement of purpose three times and gave useful comments each time.', 'The office was hard to reach by phone. I had to visit in person three times to get an update.', false, false, false, 'anonymous', null, '2026-11-01T05:00:00.000Z', null),
  ('e0000000-0000-4000-8000-000000000005', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000005', 'approved', 'AU', 'other', 2027, 'visa_granted', 15000, 5000, 'Courier and document translation.', 3, 3, 4, 4, 4, 'मेरो अभिभावकलाई सबै कुरा नेपालीमा राम्ररी बुझाइदिनुभयो। भिसा पक्का हुन्छ भनेर कहिल्यै भन्नुभएन।', 'They asked for an extra document fee that was not mentioned at the start.', true, false, false, 'initials', null, '2026-04-20T06:00:00.000Z', '2026-04-22T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000006', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000006', 'approved', 'CA', 'master', 2026, 'visa_granted', 55000, 8000, 'Courier and document translation.', 3, 3, 4, 4, 5, 'They explained every document I needed and never promised a visa. My file was ready two weeks before the deadline.', 'Nobody told me my application had been refused. I found out from the college email.', true, false, false, 'initials', null, '2026-03-21T06:00:00.000Z', '2026-03-23T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000007', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000007', 'approved', 'AU', 'other', 2027, 'in_process', null, null, null, 3, 4, 4, 4, 4, 'कागजातको सूची पहिलो दिनमै दिनुभयो। कुन पैसा कलेजलाई र कुन कन्सल्टेन्सीलाई जान्छ भनेर प्रस्ट बताउनुभयो।', 'After the visa came, they stopped answering my messages.', true, false, false, 'anonymous', null, '2026-02-23T06:00:00.000Z', '2026-02-25T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000008', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000008', 'approved', 'AU', 'master', 2027, 'visa_granted', 75000, 28000, 'Courier and document translation.', 4, 4, 5, 5, 4, 'Replies came the same day, even on Saturdays. I always knew what the next step was.', 'Nothing serious. The waiting room is small and gets very crowded in the afternoon.', true, false, false, 'anonymous', null, '2026-10-16T06:00:00.000Z', '2026-10-18T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000009', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000009', 'approved', 'AU', 'other', 2025, 'visa_granted', 20000, null, null, 3, 4, 4, 3, null, 'After I got my visa they still helped me find a room and explained the airport process.', 'फोन उठाउनुहुन्न थियो। जानकारी लिन पटक-पटक अफिस नै जानुपर्‍यो।', true, false, true, 'name', null, '2026-07-08T06:00:00.000Z', '2026-07-10T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000010', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000010', 'approved', 'AU', 'master', 2025, 'visa_granted', 85000, null, null, 5, 5, 5, 5, 5, 'They told me clearly which costs go to the college and which go to them.', 'The office was hard to reach by phone. I had to visit in person three times to get an update.', true, true, false, 'name', null, '2026-04-19T06:00:00.000Z', '2026-04-21T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000011', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000011', 'approved', 'CA', 'master', 2025, 'visa_granted', 85000, 30000, 'Courier and document translation.', 5, 4, 5, 5, 5, 'They told me clearly which costs go to the college and which go to them.', 'सुरुमा नभनिएको थप शुल्क पछि मागियो। रसिद पाउन पनि धेरै दिन लाग्यो।', true, false, false, 'name', null, '2026-05-27T06:00:00.000Z', '2026-05-29T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000012', 'c0000000-0000-4000-8000-000000000001', null, 'd0000000-0000-4000-8000-000000000012', 'approved', 'GB', 'master', 2027, 'in_process', 70000, 23000, 'Courier and document translation.', 4, 4, 3, 4, 3, 'After I got my visa they still helped me find a room and explained the airport process.', 'They pushed one college strongly. I felt they did not want to show me other options.', false, true, false, 'anonymous', null, '2026-04-17T06:00:00.000Z', '2026-04-19T06:00:00.000Z'),
