  ('e0000000-0000-4000-8000-000000000055', 'c0000000-0000-4000-8000-000000000008', 'b0000000-0000-4000-8000-000000000071', 'd0000000-0000-4000-8000-000000000015', 'approved', 'JP', 'language', 2025, 'visa_granted', 75000, 12000, 'Courier and document translation.', 3, 4, 3, 4, null, 'कागजातको सूची पहिलो दिनमै दिनुभयो। कुन पैसा कलेजलाई र कुन कन्सल्टेन्सीलाई जान्छ भनेर प्रस्ट बताउनुभयो।', 'सुरुमा नभनिएको थप शुल्क पछि मागियो। रसिद पाउन पनि धेरै दिन लाग्यो।', true, true, true, 'anonymous', null, '2026-09-18T06:00:00.000Z', '2026-09-20T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000056', 'c0000000-0000-4000-8000-000000000009', 'b0000000-0000-4000-8000-000000000081', 'd0000000-0000-4000-8000-000000000016', 'approved', 'US', 'phd', 2024, 'visa_granted', 70000, 11000, 'Courier and document translation.', 4, 4, 4, 4, 4, 'All fees were written on one paper before I paid anything. There were no surprises later.', 'My file sat for almost a month before anyone looked at it.', true, true, false, 'name', null, '2026-02-26T06:00:00.000Z', '2026-02-28T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000057', 'c0000000-0000-4000-8000-000000000009', 'b0000000-0000-4000-8000-000000000081', 'd0000000-0000-4000-8000-000000000017', 'approved', 'US', 'other', 2025, 'visa_granted', 80000, null, null, 3, 2, 2, 2, 3, 'The staff were polite and patient with my parents and answered all their questions in Nepali.', 'Nobody told me my application had been refused. I found out from the college email.', false, true, false, 'initials', null, '2025-12-27T06:00:00.000Z', '2025-12-29T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000058', 'c0000000-0000-4000-8000-000000000009', null, 'd0000000-0000-4000-8000-000000000018', 'approved', 'US', 'bachelor', 2026, 'visa_refused', 65000, 27000, 'Courier and document translation.', 3, 2, 2, 3, 2, 'After I got my visa they still helped me find a room and explained the airport process.', 'My counsellor changed twice, and each time I had to explain my case again.', false, true, false, 'anonymous', null, '2026-06-03T06:00:00.000Z', '2026-06-05T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000059', 'c0000000-0000-4000-8000-000000000010', 'b0000000-0000-4000-8000-000000000091', 'd0000000-0000-4000-8000-000000000019', 'approved', 'AU', 'phd', 2024, 'visa_granted', 40000, 7000, 'Courier and document translation.', 5, 5, 5, 5, 4, 'They told me clearly which costs go to the college and which go to them.', 'My counsellor changed twice, and each time I had to explain my case again.', true, true, false, 'anonymous', null, '2026-05-03T06:00:00.000Z', '2026-05-05T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000060', 'c0000000-0000-4000-8000-000000000010', 'b0000000-0000-4000-8000-000000000091', 'd0000000-0000-4000-8000-000000000020', 'approved', 'AU', 'master', 2026, 'visa_granted', 70000, null, null, 4, 5, 4, 4, 4, 'Replies came the same day, even on Saturdays. I always knew what the next step was.', 'फोन उठाउनुहुन्न थियो। जानकारी लिन पटक-पटक अफिस नै जानुपर्‍यो।', true, false, false, 'anonymous', null, '2026-08-18T06:00:00.000Z', '2026-08-20T06:00:00.000Z'),
  ('e0000000-0000-4000-8000-000000000061', 'c0000000-0000-4000-8000-000000000011', 'b0000000-0000-4000-8000-000000000101', 'd0000000-0000-4000-8000-000000000001', 'approved', 'FI', 'master', 2025, 'visa_granted', 50000, null, null, 3, 4, 4, 4, null, 'The staff were polite and patient with my parents and answered all their questions in Nepali.', 'I was told the offer letter would come in two weeks. It took seven.', true, false, false, 'initials', null, '2025-12-22T06:00:00.000Z', '2025-12-24T06:00:00.000Z');
