  ('f0000000-0000-4000-8000-000000000001', 'e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', null, 'Thank you for the honest feedback. We have added a second phone line and now send weekly updates by message.', 'approved', '2026-09-10T06:00:00.000Z'),
  ('f0000000-0000-4000-8000-000000000002', 'e0000000-0000-4000-8000-000000000014', 'c0000000-0000-4000-8000-000000000002', null, 'We are sorry about the delay. Your counsellor has left the company. We now assign two counsellors to every file.', 'approved', '2026-02-27T06:00:00.000Z'),
  ('f0000000-0000-4000-8000-000000000003', 'e0000000-0000-4000-8000-000000000023', 'c0000000-0000-4000-8000-000000000003', null, 'Thank you for your kind words. We wish you the best with your studies.', 'approved', '2025-12-22T06:00:00.000Z');
